package dev.cloudpilot.knowledge;

import java.util.UUID;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

/**
 * One section of a runbook. The search_vector column is generated by PostgreSQL and is
 * deliberately not mapped here: Java never writes it, and reading it is SQL's job.
 */
@Entity
@Table(name = "runbook_chunks")
public class RunbookChunk {

    @Id
    private UUID id;

    @Column(name = "runbook_id", nullable = false)
    private UUID runbookId;

    @Column(nullable = false)
    private int ordinal;

    @Column(nullable = false)
    private String heading;

    @Column(nullable = false)
    private String content;

    protected RunbookChunk() {
        // for JPA
    }

    public RunbookChunk(UUID runbookId, int ordinal, String heading, String content) {
        this.id = UUID.randomUUID();
        this.runbookId = runbookId;
        this.ordinal = ordinal;
        this.heading = heading;
        this.content = content;
    }

    public UUID getId() {
        return id;
    }

    public UUID getRunbookId() {
        return runbookId;
    }

    public int getOrdinal() {
        return ordinal;
    }

    public String getHeading() {
        return heading;
    }

    public String getContent() {
        return content;
    }
}
